--[=[
	@class WuKongRobloxProductHelper

	悟空罗布乐思商品帮助类

	
	```lua
	require(game.ReplicatedStorage.WuKong.WuKongRobloxProductHelper)
	```

	:::caution

	`require()` 本模块时, 不需要等待悟空框架准备好.

	:::
	

]=]

local rs = game:GetService("ReplicatedStorage")
require(rs.WuKong.c2l)

local tablesProvider = _G.wdm.WuKong.Ioc.WuKongRbxTablesProvider
local helper = _G.wdm.WuKong.Vendor.Helper.RobloxProductHelper

local WuKongRobloxProductHelper = {}

-- 根据商人ID,获取商人路径
function WuKongRobloxProductHelper.GetVendorPath(container, vendorId)
	return helper.GetVendorPath(container, vendorId)
end

-- 根据Roblox商品Id,获取对应的商品路径
function WuKongRobloxProductHelper.GetVendorPathByRobloxId(container, robloxId)
	local tables = tablesProvider.BuildOrGetTables()
	return helper.GetVendorPathByRobloxId(container, robloxId, tables)
end

-- 根据Roblox商品Id,获取对应的商品路径
function WuKongRobloxProductHelper.GetProductTypeByRobloxId(robloxId)
	local tables = tablesProvider.BuildOrGetTables()
	return helper.GetProductTypeByRobloxId(robloxId, tables)
end

return WuKongRobloxProductHelper
